
# 1 "JLex.fsl"
 
 (* File microJ/Jlex.fsl 
    Lexer for a Java like language (micro-Java)
    sestoft@itu.dk, nh@itu.dk * 2025-05-18
  *)

module JLex

open FSharp.Text.Lexing
open JPar

let lexemeAsString lexbuf = 
    LexBuffer<char>.LexemeString lexbuf

(* Distinguish keywords from identifiers: *)

let keyword s =
  match s with
      "boolean" -> BOOL
    | "class"   -> CLASS 
    | "extends" -> EXTENDS
    | "else"    -> ELSE
    | "false"   -> CSTBOOL false
    | "for"     -> FOR
    | "if"      -> IF
    | "int"     -> INT
    | "string"  -> STRING
    | "new"     -> NEW
    | "null"    -> NULL
    | "return"  -> RETURN
    | "true"    -> CSTBOOL true
    | "void"    -> VOID
    | "while"   -> WHILE
    | _         -> NAME s;

(* Java escapes, see jls25, §3.10.7 *)
let javaEscape s = 
    match s with
    | "\\b"  -> '\u0008'
    | "\\s"  -> '\u0020'
    | "\\t"  -> '\u0009'
    | "\\n"  -> '\u000a'
    | "\\f"  -> '\u000c'
    | "\\r"  -> '\u000d'
    | "\\\"" -> '\u0022'
    | "\\\'" -> '\u0027'    
    | "\\\\" -> '\u005c'
    | _      -> failwith "Lexer error: impossible Java escape"

